import{_ as e,o as a,c as r,a0 as o}from"./chunks/framework.Bmhw_dvp.js";const m=JSON.parse('{"title":"이용약관","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://dira.proofer.tech/terms"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"dira"}],["meta",{"property":"og:locale","content":"ko_KR"}],["meta",{"property":"og:url","content":"https://dira.proofer.tech/terms"}],["meta",{"property":"og:title","content":"이용약관"}],["meta",{"property":"og:description","content":"티켓을 큐에 넣으면 cron에 물린 워커가 claude 세션에 넘깁니다. 파일시스템이 곧 큐인 티켓 디스패처."}],["meta",{"property":"og:image","content":"https://dira.proofer.tech/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"name":"twitter:card","content":"summary_large_image"}]]},"headers":[],"relativePath":"terms.md","filePath":"terms.md"}'),d={name:"terms.md"};function i(n,t,h,c,p,l){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="이용약관" tabindex="-1">이용약관 <a class="header-anchor" href="#이용약관" aria-label="Permalink to &quot;이용약관&quot;">​</a></h1><p>프루퍼 주식회사(이하 &quot;회사&quot;)가 제공하는 dira(엔진과 앱을 합친 이름)의 이용조건을 정합니다.</p><h2 id="_1-이-도구가-무엇을-하는가" tabindex="-1">1. 이 도구가 무엇을 하는가 <a class="header-anchor" href="#_1-이-도구가-무엇을-하는가" aria-label="Permalink to &quot;1. 이 도구가 무엇을 하는가&quot;">​</a></h2><p>dira는 에이전트 CLI(<code>claude</code> 등)에게 사용자의 파일을 읽고 고치게 하는 도구입니다. 큐 루트로 삼을 디렉터리를 정하는 것도, 그 안에 무엇을 커밋할지 판단하는 것도, 그 결과를 받아들이는 것도 전부 사용자의 몫입니다. 회사는 사용자 파일에 접근하지 않습니다. 엔진과 워커는 사용자의 맥에서 사용자의 권한으로 돕니다.</p><p>이 조항은 면책 문구이기 전에 사실 고지입니다. dira를 큐 루트로 등록한 디렉터리에는 그 디렉터리에 대한 쓰기 권한을 가진 에이전트가 커밋까지 만들 수 있습니다. 사용자는 그 사실을 알고 큐 루트를 정해야 합니다.</p><h2 id="_2-라이선스와-무보증" tabindex="-1">2. 라이선스와 무보증 <a class="header-anchor" href="#_2-라이선스와-무보증" aria-label="Permalink to &quot;2. 라이선스와 무보증&quot;">​</a></h2><p>엔진과 앱은 MIT 라이선스로 배포합니다. 소스는 <a href="https://github.com/proofer-tech/dira" target="_blank" rel="noreferrer">github.com/proofer-tech/dira</a>에 공개돼 있습니다. MIT가 정하는 그대로, dira는 <strong>어떤 형태의 보증도 없이(&quot;AS IS&quot;) 제공됩니다.</strong> 특정 목적에의 적합성, 상품성, 비침해에 대한 묵시적 보증을 포함해 어떤 보증도 하지 않습니다. dira를 실행해 만들어지는 결과(에이전트가 고친 코드, 만든 커밋 포함)에 대한 책임은 사용자에게 있습니다.</p><h2 id="_3-서드파티" tabindex="-1">3. 서드파티 <a class="header-anchor" href="#_3-서드파티" aria-label="Permalink to &quot;3. 서드파티&quot;">​</a></h2><p>dira는 사용자가 이미 설치·인증한 에이전트 CLI(<code>claude</code> 등)를 호출해 씁니다. 그 CLI의 이용약관·요금·가용성은 사용자와 그 제공자 사이의 것입니다. 회사는 그 계약의 당사자가 아니고, 그 사이에 서지도 않습니다. 에이전트 CLI 자체의 동작이나 장애는 회사가 책임지지 않습니다.</p><h2 id="_4-요금" tabindex="-1">4. 요금 <a class="header-anchor" href="#_4-요금" aria-label="Permalink to &quot;4. 요금&quot;">​</a></h2><p>dira는 현재 무료입니다. 계정도, 서버도, 요금도 없습니다. 유료 플랜이 생기면 적용 전에 이 페이지를 통해 미리 고지합니다.</p><h2 id="_5-변경" tabindex="-1">5. 변경 <a class="header-anchor" href="#_5-변경" aria-label="Permalink to &quot;5. 변경&quot;">​</a></h2><p>이 약관을 바꿀 때는 이 페이지를 갱신하는 것으로 고지합니다. 변경이 있으면 아래 시행일을 그 날짜로 올립니다.</p><h2 id="_6-사업자-정보" tabindex="-1">6. 사업자 정보 <a class="header-anchor" href="#_6-사업자-정보" aria-label="Permalink to &quot;6. 사업자 정보&quot;">​</a></h2><table tabindex="0"><thead><tr><th>항목</th><th>내용</th></tr></thead><tbody><tr><td>상호</td><td>프루퍼 주식회사</td></tr><tr><td>대표자</td><td>임한솔</td></tr><tr><td>사업자등록번호</td><td>337-81-03650</td></tr><tr><td>주소</td><td>서울 강남구 강남대로112길 47, 2층 421A</td></tr><tr><td>문의</td><td>info@proofer.tech</td></tr></tbody></table><h2 id="_7-시행일" tabindex="-1">7. 시행일 <a class="header-anchor" href="#_7-시행일" aria-label="Permalink to &quot;7. 시행일&quot;">​</a></h2><p>이 약관은 2026-08-02부터 시행합니다.</p>',17)])])}const _=e(d,[["render",i]]);export{m as __pageData,_ as default};
